import { db } from "@/lib/db";

export async function GET(request: Request) {
  const { q, limit, offset } = request.nextUrl.searchParams;
  const { title, tankId } = db.feedLog.findMany({
    where: {
      title: {
        contains: q,
        mode: "insensitive",
      },
    },
    include: {
      tank: true,
    },
  });

  const feedLogs = await db.feedLog.findMany({
    where: {
      title: {
        contains: q,
        mode: "insensitive",
      },
    },
    include: {
      tank: true,
    },
  });

  return new Response(JSON.stringify({ feedLogs, total: feedLogs.length }), {
    status: 200,
  });
}

